<!doctype html><html lang="id"><head><meta charset="utf-8"><title>{{ $invoice->number }}</title><style>body{font-family:DejaVu Sans,sans-serif;color:#102338;margin:35px;font-size:13px}.top{display:flex;justify-content:space-between;border-bottom:3px solid #0d9488;padding-bottom:20px}.brand{font-size:26px;font-weight:bold;color:#0f766e}.muted{color:#607080}.box{margin-top:30px;display:table;width:100%}.col{display:table-cell;width:50%;vertical-align:top;line-height:1.7}table{width:100%;border-collapse:collapse;margin-top:30px}th{background:#e6f5f2;text-align:left}td,th{padding:12px;border-bottom:1px solid #d9e3e7}.right{text-align:right}.total{font-size:20px;font-weight:bold;color:#0f766e}.paid{font-weight:bold;color:#0f766e}.footer{margin-top:35px;border-top:1px solid #ddd;padding-top:20px}.actions{margin-bottom:20px}@media print{.actions{display:none}@page{size:A4;margin:12mm}}</style></head><body><div class="actions"><button onclick="window.print()">Cetak Faktur</button> <a href="{{ route('invoices.pdf',$invoice) }}">Download PDF</a></div><div class="top"><div>@if($logoData)<img src="{{ $logoData }}" alt="Logo" style="max-width:80px;max-height:60px;vertical-align:middle;margin-right:10px">@endif <div class="brand">{{ $invoice->snapshot['company'] }}</div><div class="muted">{{ $invoice->snapshot['address'] }}<br>{{ $invoice->snapshot['whatsapp'] }}</div></div><div class="right"><h1>FAKTUR</h1><strong>{{ $invoice->number }}</strong><br><span class="paid">{{ strtoupper($invoice->status) }}</span></div></div><div class="box"><div class="col"><strong>Ditagihkan kepada</strong><br>{{ $invoice->snapshot['customer'] }}<br>{{ $invoice->snapshot['customer_phone'] }}<br>Kode booking: {{ $invoice->booking->code }}</div><div class="col"><strong>Detail perjalanan</strong><br>{{ $invoice->snapshot['origin'] }} → {{ $invoice->snapshot['destination'] }}<br>{{ \Carbon\Carbon::parse($invoice->snapshot['departs_at'])->translatedFormat('d F Y, H:i') }} WIB<br>{{ $invoice->snapshot['vehicle'] }} · {{ $invoice->snapshot['plate'] }}<br>Kursi {{ implode(', ',$invoice->snapshot['seats']) }}</div></div><table><thead><tr><th>Rincian</th><th class="right">Jumlah</th><th class="right">Harga</th><th class="right">Total</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr><td>{{ $item->description }}</td><td class="right">{{ $item->quantity }}</td><td class="right">Rp{{ number_format($item->unit_price,0,',','.') }}</td><td class="right">Rp{{ number_format($item->amount,0,',','.') }}</td></tr>@endforeach @if($invoice->snapshot['discount'])<tr><td>Diskon</td><td></td><td></td><td class="right">-Rp{{ number_format($invoice->snapshot['discount'],0,',','.') }}</td></tr>@endif<tr><td colspan="3" class="right total">TOTAL</td><td class="right total">Rp{{ number_format($invoice->snapshot['total'],0,',','.') }}</td></tr></tbody></table><div class="footer"><div>Metode pembayaran: <strong>{{ strtoupper($invoice->snapshot['method']) }}</strong><br>Diterbitkan: {{ $invoice->issued_at->translatedFormat('d F Y H:i') }} WIB</div><div class="right"><img src="{{ $qr }}" alt="QR verifikasi" width="110" height="110"><br><span class="muted">Pindai untuk verifikasi faktur</span></div><p class="muted">Faktur ini adalah bukti transaksi komersial, bukan Faktur Pajak.</p></div></body></html>
